/*
 * A257902  Sequence (d(n)) generated by Algorithm (in Comments) with a(1) = 0
 *          and d(1) = 2.
 * https://oeis.org/A257902
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, sign
 * Formula:   not stated
 * Range:     i8 n <= 137, i16 n <= 1000, i32 n <= 1000, i64 n <= 1000,
 *            i128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * A257902: d(n) generated by the algorithm described in the OEIS entry.
 * d(1) = 2, a(1) = 0. For k ≥ 1:
 *   let h be the least integer > –a(k) such that
 *   h ∉ D(k) and a(k)+h ∉ A(k).
 *   then a(k+1) = a(k)+h, d(k+1) = h.
 * This implementation builds the sequences on demand and caches them
 * so that calls may arrive in any order.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

/* Helper: linear search in an array of seq_t */
static bool contains(const seq_t *arr, size_t sz, seq_t val)
{
    for (size_t i = 0; i < sz; ++i)
        if (arr[i] == val)
            return true;
    return false;
}

seq_t a(idx_t n)
{
    /* Static cache */
    static seq_t *A = NULL;
    static seq_t *D = NULL;
    static size_t len = 0;      /* current number of computed terms */
    static size_t cap = 0;      /* capacity of the arrays */

    /* Lazy initialisation: first terms a(1)=0, d(1)=2 */
    if (len == 0) {
        cap = 16;
        A = (seq_t *)malloc(cap * sizeof(seq_t));
        D = (seq_t *)malloc(cap * sizeof(seq_t));
        if (!A || !D) abort();      /* out of memory */
        A[0] = (seq_t)0;
        D[0] = (seq_t)2;
        len = 1;
    }

    /* Expand the cache until we have term n */
    while (len < (size_t)n) {
        seq_t a_k = A[len - 1];          /* a(k) for current k = len */
        seq_t low = -a_k + (seq_t)1;      /* lowest candidate: > -a(k) */

        seq_t h;                          /* will hold the chosen h */
        for (h = low; ; ++h) {
            if (contains(D, len, h))
                continue;
            seq_t sum = a_k + h;
            if (contains(A, len, sum))
                continue;
            break;                        /* valid h found */
        }

        /* Append new elements to the cache */
        if (len == cap) {
            cap *= 2;
            A = (seq_t *)realloc(A, cap * sizeof(seq_t));
            D = (seq_t *)realloc(D, cap * sizeof(seq_t));
            if (!A || !D) abort();        /* out of memory */
        }
        A[len] = a_k + h;                  /* a(k+1) */
        D[len] = h;                        /* d(k+1) */
        ++len;
    }

    /* Return the requested term d(n) */
    return D[n - 1];
}
